mapper.select:
select
e.empId,e.firstName,e.email,e.password,e.designationId,e.empCode,e.firstLoginStatus
from EmployeeInfo e where e.email=#{email}

SELECT
CASE WHEN count(email) > 0 THEN 1 ELSE 0 END FROM EmployeeInfo WHERE
email = #{email}

mapper.update:
update PhoneNumberInfo set empId=#{empId},phoneNumberType=#{phoneNumberType}
,phoneNumber=#{phoneNumber},status=#{status},
lastModifiedOn=now() where empId=#{empId} and phoneNumberId=#{phoneNumberId}

mapper.select:
select empId,empCode,firstName,middleName,lastName,email,dob,doj,designationId,status,addedOn,lastModifiedOn,firstLoginStatus from EmployeeInfo 


  concat(firstName,lastName) like #{firstName}



  or empCode like #{empCode} 


  or email like #{email} 


  doj between doj=#{fromDate} and doj=#{toDate}
